package com.ias.finance;
import org.junit.jupiter.api.*;
import java.util.*;
import java.util.concurrent.*;
import static com.ias.finance.FeeGroup.*;
import static com.ias.finance.JdbcFeeGroups.*;
import static org.junit.jupiter.api.Assertions.*;

class QuoteDecisionTest {
 JdbcFeeGroupsTest f;JdbcFeeGroups store;Submit quote;Actor customer=new Actor(1,99);
 @BeforeEach void setup()throws Exception{f=new JdbcFeeGroupsTest();f.setup();Access base=f.authority;store=new JdbcFeeGroups(f.source,new Access(){public void current(Actor a,Identity o,String action){base.current(a,o,action);}public void submission(Actor a,Identity o,Submit c,QuoteDetails d){base.submission(a,o,c,d);}public void approval(Actor a,Identity o,UUID id,ApprovalFact fact){}public void verifiedCost(Actor a,Identity o,CostFact fact){}public void execution(Actor a,Identity o,UUID id){}public void customerConfirmation(Actor a,Identity o,QuoteVersion q){if(!a.equals(customer))throw new SecurityException("ADMIN_REQUIRED");}public void quoteDecision(Actor a,Identity o,QuoteVersion q,UUID op,String action,long version,String reason){if(action.equals("CUSTOMER_QUOTE_REJECTED"))customerConfirmation(a,o,q);else if(!a.equals(f.actor))throw new SecurityException("AUTHOR_REQUIRED");}});quote=f.command(0,250000,200000,Set.of());store.submit(f.actor,f.owner,quote,new QuoteDetails(true,"完整当前报价等待客户确认",f.details(quote).kinds()));}
 Receipt reject(UUID op)throws Exception{return store.decide(customer,f.owner,op,1,quote.applicationId(),1,"CUSTOMER_QUOTE_REJECTED","客户明确拒绝当前收费方案");}
 @Test void rejectPreservesHistoricalFinancialMarkerAndCreatesNoApproval()throws Exception{UUID op=UUID.randomUUID();var receipt=reject(op);assertEquals(receipt,reject(op));assertEquals(0,f.count("finance_approval_request"));assertEquals(1,f.count("finance_quote_decision"));assertEquals("REJECTED",store.quoteStatus(customer,f.owner,quote.applicationId()).get("customerDecision"));assertTrue(store.read(customer,f.owner).everRequiredFinance());assertEquals(0,store.read(customer,f.owner).qCents());assertEquals(250000,store.quote(customer,f.owner,quote.applicationId()).basis().bCents());assertThrows(IllegalStateException.class,()->store.confirm(customer,f.owner,UUID.randomUUID(),2,quote.applicationId(),1));assertThrows(IllegalStateException.class,()->store.approved(f.actor,f.owner,UUID.randomUUID(),2,quote.applicationId(),new ApprovalFact(UUID.randomUUID(),true,true)));}
 @Test void withdrawPreservesQuoteAndRejectsNewDecisionKey()throws Exception{UUID op=UUID.randomUUID();var receipt=store.decide(f.actor,f.owner,op,1,quote.applicationId(),1,"QUOTE_WITHDRAWN","原发起人撤回当前报价方案");assertEquals(receipt,store.decide(f.actor,f.owner,op,1,quote.applicationId(),1,"QUOTE_WITHDRAWN","原发起人撤回当前报价方案"));assertEquals(1,f.count("finance_quote_version"));assertThrows(IllegalStateException.class,()->reject(UUID.randomUUID()));assertEquals(0,f.count("finance_approval_request"));}
 @Test void confirmedCannotBeRejectedAndCurrentAdminRechecked()throws Exception{store.confirm(customer,f.owner,UUID.randomUUID(),1,quote.applicationId(),1);assertThrows(IllegalStateException.class,()->store.decide(customer,f.owner,UUID.randomUUID(),2,quote.applicationId(),1,"CUSTOMER_QUOTE_REJECTED","已确认不能直接改为拒绝"));assertThrows(SecurityException.class,()->store.decide(f.actor,f.owner,UUID.randomUUID(),2,quote.applicationId(),1,"CUSTOMER_QUOTE_REJECTED","不是当前企业管理员拒绝"));}
 @Test void missingFreezeAuthorityFailsClosed()throws Exception{var unbound=new JdbcFeeGroups(f.source,f.authority);assertThrows(com.ias.trust.Problem.class,()->unbound.decide(f.actor,f.owner,UUID.randomUUID(),1,quote.applicationId(),1,"QUOTE_WITHDRAWN","冻结权威端口尚未提供必须拒绝"));assertEquals(0,f.count("finance_quote_decision"));}
 @Test void auditFaultRollbackAndOriginalUuidRecovery()throws Exception{try(var db=f.source.getConnection();var q=db.createStatement()){q.execute("ALTER TABLE finance_audit ADD CONSTRAINT fail_reject CHECK(action_name<>'CUSTOMER_QUOTE_REJECTED')");}UUID op=UUID.randomUUID();assertThrows(Exception.class,()->reject(op));assertEquals(0,f.count("finance_quote_decision"));assertEquals(1,store.read(customer,f.owner).version());assertEquals(2,f.count("finance_operation"));try(var db=f.source.getConnection();var q=db.createStatement()){q.execute("ALTER TABLE finance_audit DROP CONSTRAINT fail_reject");}reject(op);assertEquals(1,f.count("finance_quote_decision"));}
 @Test void confirmAndRejectRaceHasOneWinnerAndNoFakeApproval()throws Exception{try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var gate=new CountDownLatch(1);var a=pool.submit(()->{gate.await();try{reject(UUID.randomUUID());return true;}catch(IllegalStateException expected){return false;}});var b=pool.submit(()->{gate.await();try{store.confirm(customer,f.owner,UUID.randomUUID(),1,quote.applicationId(),1);return true;}catch(IllegalStateException expected){return false;}});gate.countDown();assertNotEquals(a.get(),b.get());}assertEquals(1,f.count("finance_quote_decision")+f.count("finance_customer_confirmation"));assertEquals(f.count("finance_customer_confirmation"),f.count("finance_approval_request"));assertEquals(2,store.read(customer,f.owner).version());}
 @Test void terminatedQuoteOriginalSubmissionDoesNotRestoreLinesAndNewQuoteKeepsMarker()throws Exception{reject(UUID.randomUUID());store.submit(f.actor,f.owner,quote,new QuoteDetails(true,"完整当前报价等待客户确认",f.details(quote).kinds()));assertEquals(0,store.read(customer,f.owner).qCents());var next=f.command(2,10000,300000,Set.of());var receipt=store.submit(f.actor,f.owner,next,new QuoteDetails(true,"拒绝之后重新提交另一不可变报价",f.details(next).kinds()));assertTrue(receipt.basis().financialReviewRequired());assertEquals(10000,receipt.basis().qCents());assertEquals(quote.applicationId(),receipt.basis().firstFinanceTrigger().applicationId());assertThrows(IllegalStateException.class,()->store.confirm(customer,f.owner,UUID.randomUUID(),3,quote.applicationId(),1));}}
